grade.command_excerpt:
Get-Counter @('\Memory\Available MBytes','\Memory\Committed Bytes','\Processor(_Total)\% Processor Time') -SampleInterval 5 -MaxSamples 6 -ErrorAction Stop | ForEach-Object {
    $readings = $_.CounterSamples
    [pscustomobject]@{
        Time = $_.Timestamp
        FreeGiB = [math]::Round((($readings | Where-Object Path -Like '*\available mbytes').CookedValue / 1024), 2)
        CommitGiB = [math]::Round((($readings | Where-Object Path -Like '*\committed bytes').CookedValue / 1GB), 2)
        CPUPercent = [math]::Round(($readings | Where-Object Path -Like '*\% processor time').CookedValue, 1)
    }
} | Format-Table -AutoSize

Get-Counter '\Memory\Available MBytes','\Memory\Pool Nonpaged Bytes','\Memory\Pool Paged Bytes','\Processor(_Total)\% Processor Time' -SampleInterval 5 -MaxSamples 7 |
  ForEach-Object {
    $t = $_.Timestamp
    $_.CounterSamples | Select-Object @{n='Timestamp';e={$t}},Path,CookedValue
  } | Format-Table -AutoSize

Get-Counter -Counter '\Memory\Available MBytes','\Memory\Committed Bytes','\Memory\Pool Nonpaged Bytes','\Memory\Pool Paged Bytes','\Processor(_Total)\% Processor Time','\System\Processor Queue Length' -SampleInterval 5 -MaxSamples 12 |
  ForEach-Object {
    $_.Timestamp.ToString('HH:mm:ss')
    $_.CounterSamples | Select-Object Path,CookedValue | Format-Table -AutoSize
  }

Get-Counter -Counter '\Processor(_Total)\% Processor Time','\System\Processor Queue Length','\Memory\Available MBytes','\Memory\Committed Bytes','\Memory\Commit Limit','\Memory\Pool Nonpaged Bytes','\Memory\Pool Paged Bytes' -SampleInterval 5 -MaxSamples 3 |
  ForEach-Object {
    $_.Timestamp
    $_.CounterSamples | Format-Table Path,CookedValue -AutoSize
  }
